package local.pocketchat;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import java.util.*;
public class RouteQualityTestActivity extends Activity {
 JSONArray checks=new JSONArray();void check(String n,boolean b){checks.put(J.obj("name",n,"pass",b));}
 @Override public void onCreate(Bundle b){super.onCreate(b);setRequestedOrientation(1);RouteQuality q=new RouteQuality(this);long now=System.currentTimeMillis();q.configure("fixture-"+now);for(int i=0;i<10;i++){q.record("stable",300,now+i);q.record("flaky",i%3==0?-1:70,now+i);q.record("jitter",i%2==0?80:1000,now+i);}check("Recent failure rate outweighs a single fast latency",q.stats("stable",now+20).optDouble("score")<q.stats("flaky",now+20).optDouble("score"));check("Latency variation penalizes an unstable route",q.stats("stable",now+20).optDouble("score")<q.stats("jitter",now+20).optDouble("score"));q.selected("stable",now);for(int i=0;i<5;i++)q.record("fast",80,now+i);List<String> routes=Arrays.asList("stable","fast");check("Cooldown keeps a healthy current route",q.choose(routes,"stable",false,false,now+1000).equals("stable"));check("Busy chat defers performance-only switching",q.choose(routes,"stable",false,true,now+RouteQuality.COOLDOWN+1000).equals("stable"));check("Sustained better candidate can switch after cooldown",q.choose(routes,"stable",false,false,now+RouteQuality.COOLDOWN+2000).equals("fast"));q.selected("fast",now+RouteQuality.COOLDOWN+2000);q.record("fast",-1,now+RouteQuality.COOLDOWN+2100);check("One failed probe does not trigger a route switch",q.choose(routes,"fast",false,false,now+RouteQuality.COOLDOWN+2200).equals("fast"));q.record("fast",-1,now+RouteQuality.COOLDOWN+2300);check("Repeated failure permits recovery inside cooldown",q.choose(routes,"fast",true,true,now+RouteQuality.COOLDOWN+2400).equals("stable"));for(int i=0;i<25;i++)q.record("bounded",100,now+i);check("Sample history is bounded",q.stats("bounded",now+30).optInt("samples")==20);check("Expired samples do not influence scoring",q.stats("bounded",now+RouteQuality.WINDOW+1000).optInt("samples")==0);RouteQuality restored=new RouteQuality(this);check("Quality survives app recreation",restored.stats("stable",now+30).optInt("samples")==10);q.configure("different-profile");check("A different network profile starts with fresh statistics",q.stats("stable",now+30).optInt("samples")==0);try{J.write(new File(getFilesDir(),"route-quality-results.json"),J.obj("checks",checks).toString(2));}catch(Exception ignored){}finish();}
}
